  "lineage": {
    "mart_arr_truth": "-- Finance snapshot is the demo reporting reference. Differences are flagged, never overwritten.\nwith history as (\n select *,lag(finance_arr_cents,1,0) over(partition by account_id order by billing_period) as previous_arr_cents\n from {{ ref('stg_invoices') }}\n), current_invoice as (\n select * from history qualify row_number() over(partition by account_id order by billing_period desc,issued_date desc,invoice_id desc)=1\n), crm as (\n select * from {{ ref('stg_hubspot_deals') }} where stage='Closed Won'\n qualify row_number() over(partition by account_id order by close_date desc nulls last,deal_id desc)=1\n)\nselect c.account_id,c.account_name,c.tier,c.csm_owner,c.renewal_date,c.close_date,\n i.billing_period,i.payment_status,c.hubspot_arr_cents as crm_arr_cents,\n i.finance_arr_cents as arr_cents,i.previous_arr_cents,\n c.hubspot_arr_cents-i.finance_arr_cents as variance_cents,\n case when c.close_date is null then 'Missing close date'\n      when c.hubspot_arr_cents<>i.finance_arr_cents then 'ARR mismatch'\n      else 'Reconciled' end as reconciliation_status,\n case when i.previous_arr_cents=0 and i.finance_arr_cents>0 then 'New business'\n      when i.previous_arr_cents>0 and i.finance_arr_cents=0 then 'Churn'\n      when i.finance_arr_cents>i.previous_arr_cents then 'Expansion'\n      when i.finance_arr_cents<i.previous_arr_cents then 'Contraction'\n      else 'Stable' end as movement,\n i.finance_arr_cents-i.previous_arr_cents as delta_arr_cents\nfrom current_invoice i left join crm c using(account_id)\n\n",
    "mart_feature_adoption": "-- Grain: eligible account / governed feature. The fixed snapshot keeps the demo reproducible.\nwith features as (\n select unnest(['technical_doc_generated','pms_report_exported','regulatory_check_run','audit_trail_verified','ai_gap_analysis_triggered']) as feature\n), usage as (\n select account_id,event_name,\n count(*) filter(where event_time>=timestamp '2026-10-26' and event_time<timestamp '2026-11-25') as current_events,\n count(*) filter(where event_time>=timestamp '2026-09-26' and event_time<timestamp '2026-10-26') as previous_events\n from {{ ref('stg_posthog_events') }} group by account_id,event_name\n)\nselect a.account_id,a.account_name,a.tier,a.csm_owner,a.arr_cents,a.renewal_date,\n f.feature,coalesce(u.current_events,0) as current_events,coalesce(u.previous_events,0) as previous_events,\n coalesce(u.current_events,0)>=3 as adopted\nfrom {{ ref('mart_arr_truth') }} a cross join features f\nleft join usage u on u.account_id=a.account_id and u.event_name=f.feature\nwhere a.arr_cents>0\n\n",
    "stg_invoices": "-- Demo invoice field is the annualised recurring contract equivalent, in EUR.\nselect invoice_id,account_id,cast(billing_period as date) as billing_period,\n round(invoiced_arr_eur*100)::bigint as finance_arr_cents,\n payment_status,cast(issued_date as date) as issued_date\nfrom {{ ref('finance_invoices') }}\n\n",
    "stg_hubspot_deals": "-- Contract snapshots, not additive deal line items. Remove replayed deal IDs.\nselect deal_id, account_id, account_name, tier, csm_owner, deal_type, stage,\n round(hubspot_arr_eur*100)::bigint as hubspot_arr_cents,\n try_cast(close_date as date) as close_date, cast(renewal_date as date) as renewal_date\nfrom {{ ref('hubspot_deals') }}\nqualify row_number() over (partition by deal_id order by close_date desc nulls last, account_id)=1\n\n",
    "stg_posthog_events": "-- Explicit allowlist is the tracking contract. Invalid events remain in raw data.\nselect event_id,account_id,user_id,event_name,cast(timestamp as timestamp) as event_time,\n duration_sec::double as duration_sec\nfrom {{ ref('posthog_events') }}\nwhere event_name in ('technical_doc_generated','pms_report_exported','regulatory_check_run','audit_trail_verified','ai_gap_analysis_triggered')\n and account_id in (select account_id from {{ ref('stg_hubspot_deals') }})\nqualify row_number() over (partition by event_id order by timestamp desc)=1\n\n"
  },
